import { useEffect, useRef, useState } from 'preact/hooks';
import type { PDFDocumentProxy, RenderTask } from 'pdfjs-dist';
import { onceInView } from '../lib/inView';
import { renderScale, thumbnailSize } from '../pdf/thumbnail';

/** Weergavebreedte van een miniatuur in CSS-pixels. */
export const THUMBNAIL_WIDTH = 160;

/**
 * Eén miniatuur. Wordt pas getekend als hij in beeld komt, zodat een PDF met honderden
 * pagina's niet alles tegelijk hoeft te tekenen.
 */
export function Thumbnail({
  pdf,
  pageNumber,
  label,
  rotation = 0,
  decorative = false,
  caption = pageNumber,
}: {
  pdf: PDFDocumentProxy;
  pageNumber: number;
  label: string;
  /** Extra draaiing in graden, bovenop de draaiing in de PDF zelf. */
  rotation?: number;
  /** Als de omliggende knop of optie de naam al geeft: de afbeelding zelf zwijgt. */
  decorative?: boolean;
  /** Het nummer onder de miniatuur; standaard het paginanummer in de PDF. */
  caption?: number;
}) {
  const figure = useRef<HTMLElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const [visible, setVisible] = useState(false);
  const [rendered, setRendered] = useState(false);

  useEffect(() => {
    const element = figure.current;
    if (!element) return;
    return onceInView(element, () => setVisible(true));
  }, []);

  useEffect(() => {
    if (!visible) return;
    let task: RenderTask | null = null;
    let cancelled = false;
    setRendered(false);

    void (async () => {
      const page = await pdf.getPage(pageNumber);
      const target = canvas.current;
      if (cancelled || !target) return;

      const angle = (((page.rotate + rotation) % 360) + 360) % 360;
      const natural = page.getViewport({ scale: 1, rotation: angle });
      const size = thumbnailSize(natural, THUMBNAIL_WIDTH);
      const viewport = page.getViewport({
        scale: renderScale(natural.width, THUMBNAIL_WIDTH, window.devicePixelRatio),
        rotation: angle,
      });
      target.width = Math.round(viewport.width);
      target.height = Math.round(viewport.height);
      target.style.width = `${size.width}px`;
      target.style.height = `${size.height}px`;

      task = page.render({ canvas: target, viewport });
      try {
        await task.promise;
        if (!cancelled) setRendered(true);
      } catch {
        // Afgebroken (bijvoorbeeld bij sluiten): niets aan de hand.
      } finally {
        // De miniatuur staat nu op het canvas; pdf.js mag de uitgepakte pagina
        // (lettertypen, afbeeldingen van scans) weer uit het geheugen halen.
        page.cleanup();
      }
    })();

    return () => {
      cancelled = true;
      task?.cancel();
    };
  }, [visible, pdf, pageNumber, rotation]);

  return (
    <figure
      ref={figure}
      class="thumb"
      data-rendered={rendered ? 'true' : 'false'}
      data-rotation={rotation}
    >
      <div class="thumb__page">
        {decorative ? (
          <canvas ref={canvas} aria-hidden="true" />
        ) : (
          <canvas ref={canvas} role="img" aria-label={label} />
        )}
      </div>
      <figcaption aria-hidden="true">{caption}</figcaption>
    </figure>
  );
}
